namespace EMR.Web.Services.Reports;

/// <summary>A column of a pharmacy report. Fmt: text, int, qty, money, pct, date, datetime. Link = "Controller/Action:IdField" opens that page with ?id= the row's IdField (e.g. "PhSales/Bill:SaleId").</summary>
public sealed record PhRptCol(string Field, string Label, string Fmt = "text", bool Total = false, string? Link = null);

/// <summary>A tile above the report (from result set 1).</summary>
public sealed record PhRptTile(string Field, string Label, string Fmt = "money");

/// <summary>
/// A report of Reports > Pharmacy (SQLScripts/2361): its API key, its page (REPORTS.PHARMACY.*), its filters
/// (store, user, mode, kind, category, manufacturer, schedule, supplier, search, option), the choices of its option, tiles and columns.
/// DateMode "range" = from / to, "none" = as of today (the dates are not used).
/// </summary>
public sealed record PhRptDef(string Action, string Key, string Code, string Title, string Subtitle, string Group, string[] Filters,
    (string Value, string Text)[] Options, PhRptTile[] Tiles, PhRptCol[] Cols, string DateMode = "range", string? SearchHint = null, string? Tool = null)
{
    public string PageCode => "REPORTS.PHARMACY." + Action.ToUpperInvariant();
}

